import { useEffect, useMemo, useState } from "react";
import axios from "axios";
import {
  Bell,
  Bookmark,
  Check,
  ChevronRight,
  Play,
  Plus,
  Search,
  X,
} from "lucide-react";
import "./App.css";

const API = `${(process.env.REACT_APP_BACKEND_URL || "http://127.0.0.1:8000").replace(/\/$/, "")}/api`;

function Player({ movie, onClose }) {
  return (
    <div className="player-overlay" role="dialog" aria-label={`${movie.title} video player`}>
      <div className="player-top">
        <span><b>STREAMFLIX</b> · {movie.title}</span>
        <button onClick={onClose} aria-label="Close player"><X size={21} /></button>
      </div>
      <video controls autoPlay playsInline poster={movie.backdrop}>
        <source src="https://storage.googleapis.com/coverr-main/mp4/Mt_Baker.mp4" type="video/mp4" />
        Your browser does not support demo playback.
      </video>
      <div className="player-note">DEMO VIDEO · Playback position is remembered for this session</div>
    </div>
  );
}

function MovieCard({ movie, saved, onToggle, onPlay }) {
  return (
    <article className="title-card">
      <div className="poster-wrap">
        <img src={movie.poster} alt={`${movie.title} poster`} loading="lazy" />
        <div className="card-hover">
          <button className="round-play" onClick={() => onPlay(movie)} aria-label={`Play ${movie.title}`}>
            <Play size={16} fill="currentColor" />
          </button>
          <button
            className="round-action"
            onClick={() => onToggle(movie)}
            aria-label={saved ? `Remove ${movie.title} from My List` : `Add ${movie.title} to My List`}
          >
            {saved ? <Check size={16} /> : <Plus size={16} />}
          </button>
        </div>
      </div>
      <div className="card-caption">
        <strong>{movie.title}</strong>
        <div><span>{movie.year}</span><span>{movie.genre}</span><span className="match">{movie.match} match</span></div>
      </div>
    </article>
  );
}

function App() {
  const [movies, setMovies] = useState([]);
  const [watchlist, setWatchlist] = useState([]);
  const [query, setQuery] = useState("");
  const [page, setPage] = useState("home");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [playing, setPlaying] = useState(null);

  useEffect(() => {
    let active = true;

    async function loadCatalog() {
      try {
        const [movieResponse, watchlistResponse] = await Promise.all([
          axios.get(`${API}/movies`),
          axios.get(`${API}/watchlist`),
        ]);
        if (active) {
          setMovies(movieResponse.data);
          setWatchlist(watchlistResponse.data);
        }
      } catch (requestError) {
        if (active) {
          setError("Could not load the catalog. Check that the Streamflix API is running and try again.");
          console.error("Failed to load the Streamflix catalog:", requestError);
        }
      } finally {
        if (active) setLoading(false);
      }
    }

    loadCatalog();
    return () => { active = false; };
  }, []);

  const visibleMovies = useMemo(() => {
    const term = query.trim().toLowerCase();
    return movies.filter((movie) => {
      const matchesPage = page !== "list" || watchlist.some((saved) => saved.id === movie.id);
      const matchesQuery = !term || `${movie.title} ${movie.genre} ${movie.description}`.toLowerCase().includes(term);
      return matchesPage && matchesQuery;
    });
  }, [movies, page, query, watchlist]);

  async function toggleWatchlist(movie) {
    const isSaved = watchlist.some((saved) => saved.id === movie.id);
    try {
      if (isSaved) {
        await axios.delete(`${API}/watchlist/${movie.id}`);
        setWatchlist((saved) => saved.filter((item) => item.id !== movie.id));
      } else {
        await axios.post(`${API}/watchlist`, { movie_id: movie.id });
        setWatchlist((saved) => [...saved, movie]);
      }
    } catch (requestError) {
      setError(`Could not update My List for "${movie.title}". Please try again.`);
      console.error("Failed to update the Streamflix watchlist:", requestError);
    }
  }

  const featured = movies[0];

  return (
    <div className="app-shell">
      <header className="header">
        <a className="brand" href="#home" onClick={() => setPage("home")} aria-label="Streamflix home">
          <span className="brand-mark">S</span><span>STREAM<span>FLIX</span></span>
        </a>
        <nav className="nav-links" aria-label="Main navigation">
          <button className={page === "home" ? "active" : ""} onClick={() => setPage("home")}>Home</button>
          <button className={page === "list" ? "active" : ""} onClick={() => setPage("list")}>My List</button>
        </nav>
        <div className="header-actions">
          <label className="search">
            <Search size={17} />
            <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Titles, genres" aria-label="Search titles and genres" />
          </label>
          <button className="icon-btn" aria-label="Notifications"><Bell size={18} /></button>
          <button className="profile-chip" aria-label="Current profile"><span className="avatar">A</span></button>
        </div>
      </header>

      {error && <div className="error-banner" role="alert">{error}<button onClick={() => setError("")} aria-label="Dismiss error"><X size={16} /></button></div>}

      {page === "home" && featured && !query && (
        <section className="hero" style={{ backgroundImage: `linear-gradient(90deg,#0c0c0e 5%,rgba(12,12,14,.78) 42%,transparent 85%),linear-gradient(0deg,#0c0c0e,transparent 50%),url(${featured.backdrop})` }}>
          <div className="hero-copy">
            <span className="eyebrow"><i className="live-dot" /> STREAMFLIX ORIGINAL</span>
            <h1>{featured.title}</h1>
            <div className="hero-meta"><b>{featured.match} match</b><span>{featured.year}</span><span className="rating">★ {featured.rating}</span><em>HD</em></div>
            <p>{featured.description}</p>
            <div className="hero-actions">
              <button className="play-btn" onClick={() => setPlaying(featured)}><Play size={17} fill="currentColor" /> Play</button>
              <button className="more-btn" onClick={() => toggleWatchlist(featured)}>
                {watchlist.some((movie) => movie.id === featured.id) ? <Check size={17} /> : <Plus size={17} />}
                {watchlist.some((movie) => movie.id === featured.id) ? "In My List" : "My List"}
              </button>
            </div>
          </div>
          <div className="hero-pagination"><span className="current">01</span><i className="line" /><span>01</span></div>
        </section>
      )}

      <main className="content">
        <div className="welcome-line">
          <div><span className="caption">YOUR NEXT FAVORITE</span><h2>{page === "list" ? "My List" : query ? "Search results" : "Explore titles"}</h2></div>
          {page === "home" && <button className="quiet-link" onClick={() => setPage("list")}>My List <ChevronRight size={16} /></button>}
        </div>
        {loading ? (
          <p className="empty" role="status">Loading titles…</p>
        ) : visibleMovies.length ? (
          <section className="grid" aria-label={page === "list" ? "Saved titles" : "Available titles"}>
            {visibleMovies.map((movie) => (
              <MovieCard key={movie.id} movie={movie} saved={watchlist.some((item) => item.id === movie.id)} onToggle={toggleWatchlist} onPlay={setPlaying} />
            ))}
          </section>
        ) : (
          <div className="empty">
            <Bookmark size={30} />
            <h3>{page === "list" ? "Your list is waiting" : "No titles found"}</h3>
            <p>{page === "list" ? "Add a title to My List and it will show up here." : "Try searching for a different title or genre."}</p>
          </div>
        )}
      </main>
      {playing && <Player movie={playing} onClose={() => setPlaying(null)} />}
    </div>
  );
}

export default App;
